"""RouterAgent — generated by G2C (e2a_inherited); hooks implemented by hand.

Classifies a natural-language request into one intent. It decides nothing else: the
intent only selects which specialist agent the workflow runs, and that agent is again
checked by the entitlement gate before it runs.
"""
import json
import logging

from e2a_base import BaseAgent

from ..services.llm import ROUTER

INTENTS = ("PLACE_ORDER", "ORDER_STATUS", "PAYMENT_EXCEPTIONS", "POLICY_QUESTION", "UNSUPPORTED")


class RouterAgent(BaseAgent):
    """Inherits the public entry point and every NFR from BaseAgent.
    Input validation is a _validate_router_agent validator on the
    BaseValidationService subclass; the model is reached only through
    config['llm_service']."""
    agent_name = 'RouterAgent'

    def _build_messages(self, state, config=None, **kwargs) -> list:
        return [{'role': 'system', 'content': f'You are the {ROUTER}. Classify the request into exactly one '
                                              f'intent of {", ".join(INTENTS)}; answer as JSON {{"intent": ...}}.'},
                {'role': 'user', 'content': str(state.get('query', ''))}]

    def _apply_policy(self, state, config=None, **kwargs) -> None:
        approved = (config or {}).get('approved_agents')                 # kept from the G2C skeleton
        if approved is not None and self.agent_name not in approved:
            raise PermissionError(f'{self.agent_name} is not an approved agent')

    def _evaluate_output(self, response, state, config=None, **kwargs) -> float:
        text = (response or {}).get('text', '') if isinstance(response, dict) else str(response or '')
        try:
            intent = json.loads(text).get('intent')
        except (ValueError, AttributeError):
            return 0.0
        if intent not in INTENTS:
            return 0.0
        state['intent'] = intent
        return 1.0

    def _fallback(self, state, config=None, **kwargs):
        state['intent'] = 'UNSUPPORTED'
        return {'text': json.dumps({'intent': 'UNSUPPORTED'}), 'degraded': True}

    def _handle_error(self, error, state, config=None, **kwargs):
        logging.error(f'[{self.agent_name}] {error}')
        state.setdefault('errors', []).append(str(error))
        state['intent'] = 'UNSUPPORTED'
        return state
